-- Student/Guardian portal authentication schema.
-- Additive only. Do not execute until independently restorable Local and Render
-- backups have been verified and the user explicitly approves schema application.
BEGIN;

CREATE TABLE IF NOT EXISTS skolenza."StudentPortalAccount" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "NormalizedEmail" varchar(254) NOT NULL,
    "PasswordHash" varchar(500) NOT NULL,
    "IsEmailVerified" boolean NOT NULL DEFAULT false,
    "IsActive" boolean NOT NULL DEFAULT true,
    "FailedLoginCount" smallint NOT NULL DEFAULT 0,
    "LockoutEndDateTime" timestamptz NULL,
    "LastLoginDateTime" timestamptz NULL,
    "SecurityStamp" varchar(64) NOT NULL,
    "AddedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedDateTime" timestamptz NULL,
    CONSTRAINT "FK_StudentPortalAccount_Institution" FOREIGN KEY ("InstitutionId")
        REFERENCES skolenza."Institution" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentPortalAccount_FailedLoginCount" CHECK ("FailedLoginCount" >= 0)
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentPortalAccount_Institution_Email"
    ON skolenza."StudentPortalAccount" ("InstitutionId", "NormalizedEmail");

CREATE TABLE IF NOT EXISTS skolenza."StudentPortalAccountGuardian" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentPortalAccountId" bigint NOT NULL,
    "GuardianId" bigint NOT NULL,
    "LinkedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "IsActive" boolean NOT NULL DEFAULT true,
    CONSTRAINT "FK_StudentPortalAccountGuardian_Account" FOREIGN KEY ("StudentPortalAccountId")
        REFERENCES skolenza."StudentPortalAccount" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentPortalAccountGuardian_Guardian" FOREIGN KEY ("GuardianId")
        REFERENCES skolenza."Guardian" ("Id") ON DELETE RESTRICT
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentPortalAccountGuardian_Link"
    ON skolenza."StudentPortalAccountGuardian" ("InstitutionId", "StudentPortalAccountId", "GuardianId");
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentPortalAccountGuardian_Guardian"
    ON skolenza."StudentPortalAccountGuardian" ("InstitutionId", "GuardianId") WHERE "IsActive";

CREATE TABLE IF NOT EXISTS skolenza."StudentPortalAccountStudent" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentPortalAccountId" bigint NOT NULL,
    "StudentId" bigint NOT NULL,
    "LinkedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "IsActive" boolean NOT NULL DEFAULT true,
    CONSTRAINT "FK_StudentPortalAccountStudent_Account" FOREIGN KEY ("StudentPortalAccountId")
        REFERENCES skolenza."StudentPortalAccount" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentPortalAccountStudent_Student" FOREIGN KEY ("StudentId")
        REFERENCES skolenza."Student" ("Id") ON DELETE RESTRICT
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentPortalAccountStudent_Link"
    ON skolenza."StudentPortalAccountStudent" ("InstitutionId", "StudentPortalAccountId", "StudentId");
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentPortalAccountStudent_Student"
    ON skolenza."StudentPortalAccountStudent" ("InstitutionId", "StudentId") WHERE "IsActive";

CREATE TABLE IF NOT EXISTS skolenza."StudentPortalRefreshToken" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentPortalAccountId" bigint NOT NULL,
    "TokenHash" varchar(64) NOT NULL,
    "CreatedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "ExpiresDateTime" timestamptz NOT NULL,
    "RevokedDateTime" timestamptz NULL,
    "ReplacedByTokenHash" varchar(64) NULL,
    CONSTRAINT "FK_StudentPortalRefreshToken_Account" FOREIGN KEY ("StudentPortalAccountId")
        REFERENCES skolenza."StudentPortalAccount" ("Id") ON DELETE RESTRICT
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentPortalRefreshToken_Hash"
    ON skolenza."StudentPortalRefreshToken" ("TokenHash");
CREATE INDEX IF NOT EXISTS "IX_StudentPortalRefreshToken_Account"
    ON skolenza."StudentPortalRefreshToken" ("InstitutionId", "StudentPortalAccountId", "ExpiresDateTime");

CREATE TABLE IF NOT EXISTS skolenza."StudentPortalOneTimeToken" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "StudentPortalAccountId" bigint NULL,
    "GuardianId" bigint NULL,
    "StudentId" bigint NULL,
    "Purpose" smallint NOT NULL,
    "TokenHash" varchar(64) NOT NULL,
    "CreatedDateTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "ExpiresDateTime" timestamptz NOT NULL,
    "ConsumedDateTime" timestamptz NULL,
    CONSTRAINT "FK_StudentPortalOneTimeToken_Account" FOREIGN KEY ("StudentPortalAccountId")
        REFERENCES skolenza."StudentPortalAccount" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentPortalOneTimeToken_Guardian" FOREIGN KEY ("GuardianId")
        REFERENCES skolenza."Guardian" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_StudentPortalOneTimeToken_Student" FOREIGN KEY ("StudentId")
        REFERENCES skolenza."Student" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentPortalOneTimeToken_Purpose" CHECK ("Purpose" IN (1, 2)),
    CONSTRAINT "CK_StudentPortalOneTimeToken_Target" CHECK (
        (CASE WHEN "StudentPortalAccountId" IS NULL THEN 0 ELSE 1 END) +
        (CASE WHEN "GuardianId" IS NULL THEN 0 ELSE 1 END) +
        (CASE WHEN "StudentId" IS NULL THEN 0 ELSE 1 END) = 1
    )
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentPortalOneTimeToken_Hash"
    ON skolenza."StudentPortalOneTimeToken" ("TokenHash");
CREATE INDEX IF NOT EXISTS "IX_StudentPortalOneTimeToken_Expiry"
    ON skolenza."StudentPortalOneTimeToken" ("ExpiresDateTime") WHERE "ConsumedDateTime" IS NULL;

COMMIT;
